{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 다친 유기견 구조 시 보호시설(동물보호센터) 우선 이송 의무 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청장은 유기동물을 발견하거나 신고를 받으면 지체 없이 구조·보호할 수 있도록 필요한 조치를 하여야 합니다(동물보호:제10조제1항). 구조한 동물은 동물보호센터에 보호조치하여야 합니다(동물보호:제10조제3항). 다만 시장 또는 구청장은 동물의 치료와 보호를 위해 민간단체 소속자나 명예동물보호관에게 보호조치를 하도록 요청할 수 있고 예산의 범위에서 필요한 경비를 지원할 수 있습니다(동물보호:제10조제3항단서).",
          "b_ids": "동물보호:제10조제1항, 동물보호:제10조제3항, 동물보호:제10조제3항단서"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 동물보호 조례상 보호시설 입소 전 공수의 진료 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청장은 구조한 유기동물이 질병에 걸리거나 부상당한 경우에는 보호시설에 보호조치를 하기 전에 공수의가 진료하게 할 수 있습니다(동물보호:제13조제2항). 따라서 보호시설 입소 전 공수의 진료는 가능합니다.",
          "b_ids": "동물보호:제13조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
